    AND d.canteen_id = #{constraints.canteenId}


    AND d.category_id = #{constraints.categoryId}


    AND d.price >= #{constraints.minPrice}


    AND d.price <= #{constraints.maxPrice}


    AND EXISTS (
        SELECT 1
        FROM dish_tag dt
        WHERE dt.dish_id = d.id
          AND dt.tag_id IN

              #{tagId}

    )

ORDER BY (d.favorite_count * 3 + d.review_count * 2 + d.view_count) DESC, d.average_score DESC, d.id DESC
LIMIT #{limit}

SELECT di.dish_id AS dishId, di.image_url AS imageUrl FROM dish_image di WHERE di.dish_id IN
#{dishId}
ORDER BY di.is_cover DESC, di.sort_order ASC, di.id ASC

SELECT dt.dish_id AS dishId, t.id AS tagId, t.name AS tagName FROM dish_tag dt INNER JOIN tag t ON t.id = dt.tag_id WHERE dt.dish_id IN
#{dishId}
AND t.status = 'ACTIVE' ORDER BY t.sort_order ASC, t.id ASC
